INSERT INTO `history_updatenotes` VALUES (88, 'ATA24_Electric', 'V2.0.37', '1.修改左右发电机负载。');
INSERT INTO `history_updatenotes` VALUES (89, 'ATA24_Electric', 'V2.0.38', '1.修改蓄电池性能。');
INSERT INTO `history_updatenotes` VALUES (90, 'ATA24_Electric', 'V2.0.39', '1.修改雷击故障；2.修改蓄电池性能。');
INSERT INTO `history_updatenotes` VALUES (91, 'ATA24_Electric', 'V2.0.40', '1.修改DC ESS TRANS BUS故障逻辑。');
INSERT INTO `history_updatenotes` VALUES (92, 'ATA24_Electric', 'V2.0.41', '1.修改蓄电池性能；2.修改FC BUS功能；3.修改雷击故障；4.修改DC ESS TRANS BUS故障逻辑。');
INSERT INTO `history_updatenotes` VALUES (93, 'ATA24_Electric', 'V2.0.42', '1.修改内部接口命名；2.修改RAT供电时，ETRU故障的问题；3.修改GEN OFF时，IDG复位问题；4.修改闪电故障时，闪电一直触发故障的问题。');
INSERT INTO `history_updatenotes` VALUES (94, 'ATA24_Electric', 'V2.0.43', '1.修改蓄电池功能；2.修改RAT释放后，BATT  DISCHARGE消失的问题。');
INSERT INTO `history_updatenotes` VALUES (95, 'ATA24_Electric', 'V2.0.44', '1.修改LGCU的供电逻辑。');
INSERT INTO `history_updatenotes` VALUES (96, 'ATA24_Electric', 'V2.0.45', '1.修改LGCU的供电逻辑。');
INSERT INTO `history_updatenotes` VALUES (97, 'ATA24_Electric', 'V2.0.46', '1.修改Battery Discharge问题。');
INSERT INTO `history_updatenotes` VALUES (98, 'ATA24_Electric', 'V2.0.47', '1.修改电源系统性能问题；2.修改ETRU功能。');
INSERT INTO `history_updatenotes` VALUES (99, 'ATA24_Electric', 'V2.0.48', '1.修改IDG逻辑；2.修改蓄电池功能。');
INSERT INTO `history_updatenotes` VALUES (100, 'ATA24_Electric', 'V2.0.49', '1.修改蓄电池功能；2.修改IDG OIL故障逻辑。');
INSERT INTO `history_updatenotes` VALUES (101, 'ATA24_Electric', 'V2.0.50', '1.修改冷舱时，外部电接入时，AVAIL灯亮的问题；2.修改供电切换时，雨刮器发声的问题；3.修改主蓄电池和APU蓄电池充满后，TRU负载变化与电池负载变化的对应问题；4.修改空中断电几秒后又恢复供电的情况下，RAT未放出的情况。');
