INSERT INTO `package_send` VALUES (48, 1, '210', '1.更新了自动刹车RTO档位的功能特性。', '', 0, '华模', 1, 'false', 348, 1, 'A53000000004', '', NULL, NULL, '2025032672');
INSERT INTO `package_send` VALUES (49, 2, '', '1.Update autobrake RTO function characteristics.', '', 0, 'CAE', 1, 'false', 353, 1, 'A53000000009', '已加密，在发送文件夹下原位置替换', NULL, NULL, '2024071501');
INSERT INTO `package_send` VALUES (50, 4, '190,202', '1.完善RAT自动放出问题；\n2.完善BUS闪断问题。', '', 0, '华模', 1, 'false', 352, 1, 'A53000000004', '', NULL, NULL, '2025032672');
INSERT INTO `package_send` VALUES (51, 5, '', '1.补充前后盥洗室烟雾探测器功能', '', 0, '华模', 1, 'false', 351, 1, 'A53000000004', '', NULL, NULL, '2025032672');
INSERT INTO `package_send` VALUES (52, 6, '', '1.Fix a zero division risk Bug of WAI.\n2.Fix the potential zero division risk of NAI.\n3.Fix the potential zero division risk about PNU temperature.\n4.Fix the new WAI abnormal working status when use single engine bleed config.', '', 0, '华模', 1, 'false', 349, 1, 'A53000000004', '', NULL, NULL, '2025032672');
INSERT INTO `package_send` VALUES (53, 7, '', '针对IPC/IOC故障，增加IOC发给模型的信号有效性判定逻辑', '', 1, '华模', 1, 'false', 350, 1, 'A53000000004', '', NULL, NULL, '2025032672');
INSERT INTO `package_send` VALUES (54, 40, '215', '1. 完善HOT START,  High ITT（起动过程中）故障现象；\n2. 完善5级与9级引气压力与温度性能，修改模型内部变量及接口；\n3. 根据试飞数据修改N1显示限值，N1=7以下维持显示0。', '', 0, '华模', 1, 'false', NULL, 0, NULL, NULL, '2025-09-03 00:00:00', '2.0.44', NULL);
