INSERT INTO `user_operation_log` VALUES (7386, '411929', '', '{\"data\":{\"list\":[{\"updateNotes\":\"--------------以下为历史更新记录--------------\",\"version\":\"----\"},{\"updateNotes\":\"1. 完善了防火测试功能；2. 完善了发动机灭火功能；3. 完善了灭火手柄灯的问题；4. 完善了APU灭火功能；5. 完善了主起落架舱过热故障。\",\"version\":\"V2.0.17\"},{\"updateNotes\":\"1. 增加了Electrical_Smoke_In_Cockpit和Air_Conditioning_Smoke故障逻辑。\",\"version\":\"V2.0.18\"},{\"updateNotes\":\"1. 增加了Fire_Ext_Btl_Squib_Trigger_Bridge_Fail_l2和Fire_Ext_Btl_Squib_Trigger_Bridge_Fail_r1故障逻辑。\",\"version\":\"V2.0.19\"},{\"updateNotes\":\"1. 修改了Electrical_Smoke_In_Cockpit和Air_Conditioning_Smoke故障逻辑。\",\"version\":\"V2.0.20\"},{\"updateNotes\":\"1. 补充前后盥洗室烟雾探测器供电逻辑。\",\"version\":\"V2.0.21\"}]},\"error\":\"\",\"status\":1}', '2025-09-02 17:21:40', '/model/version-list');
