INSERT INTO `user_operation_log` VALUES (7388, '411929', '', '{\"data\":{\"list\":[{\"updateNotes\":\"1. 完善HOT START, ENG FAIL NORESTART（尝试重新起动）, High ITT（起动过程中），N1/N2 VIB Abnormal（起动过程中）故障现象；\n2. 完善5级与9级引气压力与温度性能。\",\"version\":\"2.0.43.1C\"},{\"updateNotes\":\"--------------以下为历史更新记录--------------\",\"version\":\"----\"},{\"updateNotes\":\"1、修改上电前发动机初始状态及起动后告警信息显示；2、  解决发动机起动过程APU引气压力过大及TOGA位发动机引气压力过大的问题；3、  完善快起与重置功能；4、  解ATA7x_Engine 决ITT未随引气状态及环境温度变化的接口问题；5、  修改起动包线逻辑；6、  解决失速状态未出现双点火的问题；7、  解决FADEC供电、滑油压力检查等部分断路器接口问题；8、  ATA7x_Engine 完善SEIZURE, HIGH ITT, HOT START等故障现象与告警信息显示；9、  完善补全推力选择相关接口。\",\"version\":\"V2.0.18\"},{\"updateNotes\":\"1、  完善RENG NO DISPATCH告警相关的故障及断路器逻辑；2、  完善发动机低压与高压级引气压力与温度性能；3、  完善ENG OIL LEVEL LO故障现象；4、  完善短舱防ATA7x_Engine 冰相关功能逻辑。\",\"version\":\"V2.0.21\"},{\"updateNotes\":\"1、  优化部分故障及断路器告警触发时机；2、  优化发动机关车后ITT与OIL TEMP趋于环境温度的变化状态；3、  新增结冰相关重置功能。\",\"version\":\"V2.0.23\"}]},\"error\":\"\",\"status\":1}', '2025-09-02 17:21:46', '/model/version-list');
