INSERT INTO `user_operation_log` VALUES (7444, '412447', '', '{\"data\":{\"list\":[{\"updateNotes\":\"--------------以下为历史更新记录--------------\",\"version\":\"----\"},{\"updateNotes\":\"1.修改外部电源供电逻辑。\",\"version\":\"V2.0.36\"},{\"updateNotes\":\"1.修改左右发电机负载。\",\"version\":\"V2.0.37\"},{\"updateNotes\":\"1.修改蓄电池性能。\",\"version\":\"V2.0.38\"},{\"updateNotes\":\"1.修改雷击故障；2.修改蓄电池性能。\",\"version\":\"V2.0.39\"},{\"updateNotes\":\"1.修改DC ESS TRANS BUS故障逻辑。\",\"version\":\"V2.0.40\"},{\"updateNotes\":\"1.修改蓄电池性能；2.修改FC BUS功能；3.修改雷击故障；4.修改DC ESS TRANS BUS故障逻辑。\",\"version\":\"V2.0.41\"},{\"updateNotes\":\"1.修改内部接口命名；2.修改RAT供电时，ETRU故障的问题；3.修改GEN OFF时，IDG复位问题；4.修改闪电故障时，闪电一直触发故障的问题。\",\"version\":\"V2.0.42\"},{\"updateNotes\":\"1.修改蓄电池功能；2.修改RAT释放后，BATT  DISCHARGE消失的问题。\",\"version\":\"V2.0.43\"},{\"updateNotes\":\"1.修改LGCU的供电逻辑。\",\"version\":\"V2.0.44\"},{\"updateNotes\":\"1.修改LGCU的供电逻辑。\",\"version\":\"V2.0.45\"},{\"updateNotes\":\"1.修改Battery Discharge问题。\",\"version\":\"V2.0.46\"},{\"updateNotes\":\"1.修改电源系统性能问题；2.修改ETRU功能。\",\"version\":\"V2.0.47\"},{\"updateNotes\":\"1.修改IDG逻辑；2.修改蓄电池功能。\",\"version\":\"V2.0.48\"},{\"updateNotes\":\"1.修改蓄电池功能；2.修改IDG OIL故障逻辑。\",\"version\":\"V2.0.49\"},{\"updateNotes\":\"1.修改冷舱时，外部电接入时，AVAIL灯亮的问题；2.修改供电切换时，雨刮器发声的问题；3.修改主蓄电池和APU蓄电池充满后，TRU负载变化与电池负载变化的对应问题；4.修改空中断电几秒后又恢复供电的情况下，RAT未放出的情况。\",\"version\":\"V2.0.50\"},{\"updateNotes\":\"1.修改飞控蓄电池充满后，TRU负载变化与电池负载变化的对应问题。\",\"version\":\"V2.0.51\"}]},\"error\":\"\",\"status\":1}', '2025-09-03 09:54:19', '/model/version-list');
